import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
Zs=np.concatenate([(C9-C9.mean(0))/C9.std(0),(M9-M9.mean(0))/M9.std(0)],1)  # global stdz (unsupervised ok)
def pcs(X,k):
    Xc=X-X.mean(0); U,S,Vt=np.linalg.svd(Xc,full_matrices=False); return Xc@Vt[:k].T
def cvK(Lin,Kf,lams,b=10,t=4.5,wl=0.3):
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f
            Kn=Kf/np.linalg.norm(Kf,axis=1,keepdims=True)
            Z=np.concatenate([wl*Lin,gelu(b*(Kn@Kn[tr].T)-t)],1)
            Y=np.eye(8)[y[tr]]-1/8
            for l in lams:
                Wt,bb=ridge_W(Z[tr],Y,l); res[l]+=((Z[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
print('full', cvK(Zs,Zs,[10,30]))
for k in [64,128,256,384]:
    P=pcs(Zs,k); print('concatPC',k, cvK(Zs,P,[10,30]))
for k1,k2 in [(128,128),(256,128),(384,192)]:
    P=np.concatenate([pcs(Zs[:,:768],k1),pcs(Zs[:,768:],k2)],1); print('sepPC',k1,k2, cvK(Zs,P,[10,30]))
